import type { Avatar, Prefs, Progress, Recipe } from "@golden/shared";
import { bigint, bigserial, boolean, index, integer, jsonb, pgTable, primaryKey, serial, smallint, text, timestamp, uuid } from "drizzle-orm/pg-core";
import { user } from "./auth-schema.js";

// Better Auth tables (user/session/account/verification), generated by `npx auth@latest generate`.
// Regenerate that file rather than hand-editing it when auth plugins change.
export * from "./auth-schema.js";

// First table: proves migrations apply to a fresh Neon branch and gives /health a row to read.
export const appMeta = pgTable("app_meta", {
  id: serial("id").primaryKey(),
  key: text("key").notNull().unique(),
  value: text("value").notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

const owner = () =>
  uuid("user_id")
    .notNull()
    .references(() => user.id, { onDelete: "cascade" });

// One row per user: skill level + onboarding prefs (formerly the bac-skill / bac-prefs cookies,
// which the web app still keeps as a device cache and as the edge middleware's gate signal).
export const profiles = pgTable("profiles", {
  userId: uuid("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  skillLevel: text("skill_level").notNull(),
  prefs: jsonb("prefs").$type<Prefs>().notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

// Device lists (D2). Each is replaced whole on sync; `position` keeps the device's order.
export const savedRecipes = pgTable(
  "saved_recipes",
  { userId: owner(), slug: text("slug").notNull(), href: text("href").notNull(), title: text("title").notNull(), image: text("image"), minutes: integer("minutes").notNull(), position: integer("position").notNull() },
  (t) => [primaryKey({ columns: [t.userId, t.slug] })],
);

export const shoppingItems = pgTable(
  "shopping_items",
  {
    userId: owner(),
    // "<recipeSlug>:<line index>", the device's de-dupe key.
    itemId: text("item_id").notNull(),
    text: text("text").notNull(),
    recipeTitle: text("recipe_title").notNull(),
    href: text("href").notNull(),
    done: boolean("done").notNull(),
    position: integer("position").notNull(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.itemId] })],
);

export const pantryItems = pgTable("pantry_items", { userId: owner(), name: text("name").notNull(), position: integer("position").notNull() }, (t) => [primaryKey({ columns: [t.userId, t.name] })]);

export const planDone = pgTable("plan_done", { userId: owner(), slug: text("slug").notNull(), position: integer("position").notNull() }, (t) => [primaryKey({ columns: [t.userId, t.slug] })]);

export const activeTimers = pgTable(
  "active_timers",
  { userId: owner(), timerId: text("timer_id").notNull(), label: text("label").notNull(), recipeSlug: text("recipe_slug").notNull(), endsAt: bigint("ends_at", { mode: "number" }).notNull(), position: integer("position").notNull() },
  (t) => [primaryKey({ columns: [t.userId, t.timerId] })],
);

// Private: only ever read by user_id; never part of the public recipes/segments/feed.
export const importedRecipes = pgTable(
  "imported_recipes",
  { userId: owner(), slug: text("slug").notNull(), sourceUrl: text("source_url"), recipe: jsonb("recipe").$type<Recipe>().notNull(), position: integer("position").notNull() },
  (t) => [primaryKey({ columns: [t.userId, t.slug] })],
);

export const feedbackMemory = pgTable("feedback_memory", {
  userId: uuid("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  sent: boolean("sent").notNull(),
  skippedAt: integer("skipped_at"),
});

// Game layer: the server's copy is the source of truth (rules in @golden/shared/progress).
export const progress = pgTable("progress", {
  userId: uuid("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  xp: integer("xp").notNull(),
  streak: integer("streak").notNull(),
  lastCookDay: text("last_cook_day"),
  dishes: integer("dishes").notNull(),
  mood: jsonb("mood").$type<Progress["mood"]>(),
  avatar: jsonb("avatar").$type<Avatar>().notNull(),
  // Daily caps on XP-earning events, counted per server UTC day.
  capDay: text("cap_day"),
  cookedToday: integer("cooked_today").notNull().default(0),
  fixedToday: integer("fixed_today").notNull().default(0),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

export const kitchenLog = pgTable(
  "kitchen_log",
  {
    userId: owner(),
    entryId: text("entry_id").notNull(),
    kind: text("kind").notNull(),
    title: text("title").notNull(),
    detail: text("detail").notNull(),
    image: text("image"),
    at: bigint("at", { mode: "number" }).notNull(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.entryId] }), index("kitchen_log_user_at_idx").on(t.userId, t.at)],
);

// Feedback and community outlive the account that wrote them (user_id set null), like Supabase did.
export const feedback = pgTable(
  "feedback",
  {
    id: bigserial("id", { mode: "number" }).primaryKey(),
    userId: uuid("user_id").references(() => user.id, { onDelete: "set null" }),
    rating: smallint("rating").notNull(),
    message: text("message"),
    mealsFinished: integer("meals_finished"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("feedback_created_idx").on(t.createdAt)],
);

export const communityPosts = pgTable(
  "community_posts",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: uuid("user_id").references(() => user.id, { onDelete: "set null" }),
    name: text("name").notNull(),
    level: text("level").notNull(),
    dish: text("dish").notNull(),
    note: text("note").notNull(),
    asksForHelp: boolean("asks_for_help").notNull().default(false),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("community_posts_created_idx").on(t.createdAt)],
);

export const communityReplies = pgTable(
  "community_replies",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    postId: uuid("post_id")
      .notNull()
      .references(() => communityPosts.id, { onDelete: "cascade" }),
    userId: uuid("user_id").references(() => user.id, { onDelete: "set null" }),
    name: text("name").notNull(),
    level: text("level").notNull(),
    body: text("body").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("community_replies_post_idx").on(t.postId, t.createdAt)],
);
